"""Campaign-approved context and proposed commitments for fictional Caprica."""

SLOGAN = "Freedom to Build. Confidence in Tomorrow."
PROMISES = [
    "The freedom to get ahead",
    "The confidence to plan your future",
    "The power to shape your own life",
]

# Every numerical forward commitment below is a proposal, not a claimed result.
# The supplied current fiscal outturn is gross debt of 69% of GDP in 2068.
PAGES = [
    dict(id="housing", part=0, title="The keys to your own future.",
         intro="A place of your own changes what you can plan: a family, a new job, a life near the people you love. Caprica needs more homes where people actually want to live.",
         everyday="A secure rental, a first home or somewhere smaller near family becomes a realistic choice, with working services ready when you move in.",
         test="50% more annual homes by 2072",
         entries=[
             ("Build 50% more homes by 2072", "Increase annual completions by 50% against the independently verified 2068 total, released within 100 days. Regional growth agreements will secure land, builders and training places before setting construction schedules. Monthly figures on starts, completions and costs will show whether building is keeping pace."),
             ("Put a clock on planning", "Give complete growth zone applications a decision within 120 days; compliant infill using approved designs gets 60 days. A missed deadline brings a fee refund and independent appeal. Safety, flood, habitat and infrastructure rules still apply, and every refusal must come with public reasons."),
             ("Build where life happens", "Allow quality apartments and homes above shops within 800 meters of rapid transit and in established town centers. Release suitable public land competitively, with construction deadlines. Reusable designs and compatible modular standards will reduce repeated design costs while keeping clear quality requirements."),
             ("Connect before people move in", "Agree ten years of water, power, school and transport capacity through regional growth compacts and a revolving Infrastructure Capacity Fund. Disclosed development levies and gains in land value repay advances. Borrowing must pass independent appraisal, cover maintenance and withstand lower than expected land receipts."),
             ("A rental you can settle into", "Give renters lasting contracts, portable deposits and enforceable standards for warmth, safety and repairs. A specialist tribunal will aim to resolve disputes within 30 days. Local rent and vacancy figures will guide new supply; rent freezes that discourage construction would leave the shortage unresolved."),
             ("A practical route to ownership", "Offer portable housing savings accounts and a capped shared ownership scheme for eligible working households buying additional new homes. Set public income limits, resale terms and subsidy costs. Support must add homes and pass fiscal checks, avoiding a bidding subsidy for properties already in short supply."),
         ], delivery="By 2069: growth compacts and planning clocks. By 2072: 50% more annual completions than in 2068."),
    dict(id="tax", part=0, title="Let work take you further.",
         intro="A raise should give you more room in the household budget. Fair, predictable taxes reward extra effort and let people decide whether to hire, return to work or save for something bigger.",
         everyday="You can see what an extra shift, a raise or a return to work means for your income before making the decision.",
         test="Keep the 20% earnings credit",
         entries=[
             ("Keep the negative income tax", "Retain the 20% earnings credit on the first 20,000 aurums of the reference income band: up to 4,000 aurums before other credits and statutory indexation. Payment comes through payroll with annual reconciliation. Each budget will include updated schedules and a straightforward route for irregular earners."),
             ("No tax rise by stealth", "Continue annual CPI indexation of the reference 20,000, 40,000, 60,000 and 80,000 aurum thresholds. Suspending it would require explicit legislation and a stated cost. A public calculator will show tax and benefit withdrawals together, exposing any point where earning more leaves a household worse off."),
             ("Childcare help when bills arrive", "Keep the childcare credit refundable and offer monthly payment. Married, unmarried and single parents will receive equal treatment. Accredited centers, family day care and providers offering longer hours can participate, subject to common safety standards, clear fees and checks that families receive the benefit."),
             ("Rates you can plan around", "Keep the established 20% VAT, 30% land value tax on its existing statutory assessment base, and 5%, 8% and 10% corporate rates in the first budget. Publish a roadmap covering five years and eligibility. Later changes need independent fiscal and distributional assessment and at least 90 days' notice."),
             ("Reward the next investment", "Allow immediate expensing of qualifying machinery, software and clean equipment. Keep the 40% research and human capital credit for audited additional spending above a disclosed recent baseline. Reject inflated transactions between related businesses and relabeled routine costs; measure productivity gains and recover improper claims."),
             ("Let employees share the success", "Tax employee shares when there is a genuine chance to sell, with rules against disguising salary. Allow capital gains deferral for qualifying reinvestment in Caprican startups. Cap and disclose these reliefs, then test whether they spread ownership and investment rather than shelter existing wealth."),
         ], delivery="First budget: indexed tax schedules, monthly credit payments and a public tax and benefit calculator."),
    dict(id="enterprise", part=0, title="Make room for the next good idea.",
         intro="The next good employer could be the bakery adding a second shop or the researcher opening a laboratory. A clear set of rules should give both the confidence to take that chance.",
         everyday="Less time chasing forms and unpaid invoices gives an independent business more time to win customers, train someone and make the next investment.",
         test="Public invoices paid within 20 working days",
         entries=[
             ("Start a business in a day", "Extend the digital business gateway to incorporate complete standard applications within one day. With consent, reuse verified information and combine routine filings. Applicants get a single tracker, a named contact and a staffed alternative. Regulated activities must still obtain the safety approvals their work requires."),
             ("Pay small suppliers on time", "Public bodies must pay undisputed small business invoices within 20 working days, with automatic interest when they miss the deadline. Report compliance and name who resolves disputes. Main contractors on public projects must pass equivalent payment terms to subcontractors, so cash reaches the firms doing the work."),
             ("Rules that earn their place", "For every unit of new material compliance cost, remove two comparable units, using independently checked calculations. Parliament can authorize justified exceptions for safety and other public interests. Review major economic regulations every seven years, keeping protections whose benefits justify their cost."),
             ("A fair chance at public contracts", "Divide suitable contracts into lots smaller firms can handle and keep insurance and turnover tests proportionate. Disclose beneficial owners, selection reasons and contract changes. Innovation competitions will buy demonstrable solutions through open testing, giving a new entrant the same fair hearing as an established supplier."),
             ("Make switching worth your while", "Strengthen the Competition Authority's investigations and interim remedies, subject to appeal. Challenge state favoritism, exclusionary platforms and excessive concentration in essential markets. Clear charges, easy switching and portable data will help customers take their business elsewhere and give better competitors room to enter."),
             ("Give new technology a fair trial", "Offer supervised trials of maritime, financial, health and clean energy technology with fixed end dates, clear liability and participant protections. Set the evaluation criteria before admission. Successful trials must qualify for ordinary approval; failed trials must close without passing undisclosed losses to the taxpayer."),
         ], delivery="By 2069: incorporation in one day and the payment duty. Annual reporting on competition and contract access."),
    dict(id="work", part=0, title="A route forward at every age.",
         intro="Your first job should lead somewhere. Your last qualification should never close every other door. We will make it easier to start, change direction and return after time spent caring.",
         everyday="You have a practical next step when work changes, with recognized training, an adviser who knows your case and support that does not vanish overnight.",
         test="90 days once eligible after four months",
         entries=[
             ("A next step within 90 days", "Anyone under 25 who has spent four months outside work or education will get a named adviser and a suitable apprenticeship, training or job offer within 90 days. Work must be paid and the place reachable. Regional results will track completion and lasting employment."),
             ("Skills that travel with you", "Create portable accounts for accredited training, funded jointly by employers and government within a stated annual budget. Give priority to shortage skills and career changes. Clear completion, employment and earnings information will guide choices; providers that consistently disappoint will lose access after a fair review."),
             ("Apprenticeships on every main street", "Let larger employers direct part of their training levy to accredited apprenticeships among their suppliers. Use unspent balances for places with small employers, supported by shared administration and recognized qualifications. Funding must buy verified training and completion, with checks against relabeling existing jobs."),
             ("Make the return to work safer", "Combine overlapping support for working adults, with a clear earnings disregard and gradual taper. Preserve essential disability and caring help. Trying work must not immediately cancel benefits. Explain transition rules in advance, and require reasons, human review and an appeal before an adverse decision stands."),
             ("A fair deal at work", "Protect the choice to join a union, bargain collectively or individually, or decline membership. Make complaints accessible and enforce pay, safety and protection from retaliation. Predictable contracts and portable benefits will support flexible work, with enforcement against employers falsely treating employees as independent contractors."),
             ("Make the opportunity reachable", "Fit training around childcare, accessible transport and rehabilitation. Recognize experience and prior learning so someone changing careers does not repeat skills they already have. Job services must agree a plan within 20 working days with claimants ready for work and explain the practical support available."),
         ], delivery="By 2070: offers within 90 days after four months outside work or education for people under 25."),
    dict(id="schools", part=0, title="Strong beginnings. Open futures.",
         intro="The school down the road should give every child a strong start. Parents need confidence in the basics; teachers need the time and backing to help each student master them.",
         everyday="Children get help early, teachers spend more time teaching, and families can understand what students are learning and where each qualification can lead.",
         test="A development check two years before school",
         entries=[
             ("Help before the first school day", "Offer a language and development check two years before school, followed by timely help where needed. Early learning will combine play, movement, curiosity and language. With parental consent and privacy safeguards, one assessment can serve education, health and care, sparing families repeated appointments."),
             ("Get the foundations right", "Protect daily reading, writing and mathematics in primary school, using proven materials and regular checks designed to guide teaching. Include science, civic knowledge and critical thinking. National standards will make expectations clear while leaving teachers professional freedom to help their students reach them."),
             ("Give teachers time to teach", "Cut duplicate reporting and provide quality lesson resources, rigorous classroom training and paid routes into shortage subjects. Reward expert teachers with senior classroom careers. Give struggling staff practical support and clear standards, with due process when performance remains inadequate and students need better."),
             ("Keep classrooms calm and focused", "Set clear behavior expectations and keep phones out of instructional time, with health and disability exceptions. Address repeated disruption early and provide alternatives where needed. Report attendance and safety with enough context to recognize the different challenges schools face, rather than rank them crudely."),
             ("Give each learner the right support", "Provide one coordinator and a legal deadline for every additional needs support plan. Maintain teaching in regional languages alongside proficiency in the national language. Coordinate meals, transport and disability assistance, so a child's ability to attend and learn does not depend on navigating several disconnected systems."),
             ("Teach the decisions life brings", "Teach contracts, compound interest, tax, media verification, constitutional rights and responsible technology use. Set independent qualification standards that explain academic, technical and apprenticeship choices clearly. Providers must report completion and students' next destinations, with context and privacy protection for small groups."),
         ], delivery="By 2069: core standards and legal deadlines for support plans. Annual school and destination reporting thereafter."),
    dict(id="science", part=0, title="Turn knowledge into opportunity.",
         intro="Caprica should be a place where people can make a discovery, master a trade and turn either into a career. Excellent universities and respected technical colleges belong in the same national ambition.",
         everyday="Students can choose a route with clear information, and researchers can build a career in Caprica without abandoning either curiosity or commercial ambition.",
         test="Standard research licenses in place by 2070",
         entries=[
             ("Technical colleges with serious ambition", "Agree regional college programs with employers in construction, maritime engineering, health, energy, advanced manufacturing and cybersecurity. Fund equipment and placements through open agreements. Portable qualifications will recognize real skills; employers will help assess whether graduates can perform the work their courses prepare them for."),
             ("The facts before you enroll", "Make completion rates, teaching hours, employment, earnings ranges and likely debt available before enrollment. These figures inform a choice; they cannot guarantee a salary. Accessible advice will help students of every age compare university, technical training and apprenticeships on a consistent basis."),
             ("Leave room for discovery", "Protect university autonomy, peer review and academic freedom, with stable competitive grants for fundamental and applied research. Any civil restriction needs a specific security or safety justification, independent scrutiny and an appeal. Valuable discovery often begins before anyone can name its commercial use."),
             ("Turn a discovery into a business", "Introduce standard licensing terms, initial testing awards with fixed end dates, and enterprise leave for researchers. Disclose who owns publicly supported discoveries and how returns are shared. Judge programs by additional private investment, commercial results and lessons from failure, rather than the volume of announcements."),
             ("Bring talent to Caprica", "Offer efficient research visas, Columbian mobility and competitive fellowships for Caprican scientists returning home. Check qualifications and screen sensitive work proportionately. Recruitment plans must include laboratory space, professional recognition and housing capacity, giving people a credible reason to build their future here."),
             ("Put ideas to a demanding test", "Open research challenges in resilient agriculture, clean power, medicines, maritime systems and secure computing to universities and smaller firms working together. Test demand and public value before expanding an award. Every scheme will have an end date and independent evaluation of its results."),
         ], delivery="By 2070: standard research licenses, regional technical agreements and public results from research commercialization."),
    dict(id="gateway", part=0, title="A gateway that creates opportunity.",
         intro="Our position at the Twin Strait is an opening to the world. Making the most of it means joining ports, skills and industry into an economy that offers opportunity well beyond the waterfront.",
         everyday="A growing port creates chances for the local apprentice, the inland food producer and the small supplier, with homes and services keeping pace.",
         test="One customs window for routine exporters",
         entries=[
             ("Make the connections before construction", "Set out a national development pipeline joining ports, freight, clean power, water, housing and skills. Rank investments by tested demand and economic value. Every expansion must account for its connecting roads, electricity and workforce before money is committed to an incomplete project."),
             ("Submit once, trade more easily", "Create one digital customs window and trusted trader corridors with Columbian partners. Inspect according to risk, with public clearance times, service standards and appeals. Maintain food, safety and biosecurity checks while ending the repeated submission of the same verified documents to different agencies."),
             ("Give investment a clear answer", "Provide a stated timetable, one responsible coordinator and predictable commercial law. Screen control of critical ports, defense, energy, telecoms and sensitive data through a narrow process with a deadline. Investors should know the rules and receive a decision without political bargaining or hidden conditions."),
             ("Open export doors for small firms", "Provide shared certification advice, commercial trade finance and practical help with digital sales, language and logistics. State fees and eligibility clearly. Measure additional exports and repayment, cap public exposure and disclose losses, so helping a promising exporter never becomes an unlimited taxpayer guarantee."),
             ("Give industries room to grow", "Connect maritime services, clean technology, food processing, research and digital trade to the skills and infrastructure they need. Support must follow credible private demand. Firms will compete for customers and contracts, with government building useful capacity and declining to guarantee any company's commercial survival."),
             ("Make growth worth living near", "Major projects receiving public support must advertise apprenticeships and supplier opportunities and disclose local infrastructure costs and benefits. Add housing and service capacity alongside jobs. Nearby households need to afford a place to live, and regional producers need a usable route to the new market."),
         ], delivery="First year: a ranked development pipeline, customs service standards and transparent investment screening deadlines."),
    dict(id="regions", part=0, title="Build a future close to home.",
         intro="Leaving home should be a choice. From Ambrosia's farms to the smaller ports, useful connections and local skills can give people more reasons to build a life in their own community.",
         everyday="Reliable water, a usable internet connection and a route to market help farms and local firms grow, making staying close to home a stronger choice.",
         test="Rural water repair priorities set by 2069",
         entries=[
             ("Keep more value close to the farm", "Share the cost of precision fertilizer, smart irrigation, soil monitoring and safe processing equipment through accounts with fixed end dates. Pay for verified adoption and measurable benefits. Local processing and refrigerated storage will help producers earn more from their goods before those goods leave the region."),
             ("Clean water and living landscapes", "Make rural water test results and repair schedules public, prioritizing health risks. Use stewardship payments, conservation easements and independently assessed habitat credits to reward care for the land. Protect major forests and sensitive coasts, with clear standards for tourism and productive use."),
             ("Give small ports useful connections", "Test rural freight and ferry upgrades for reliability, safety and economic value, and tender essential routes openly. Offer discounts on genuinely spare capacity outside busy periods where they help small producers. Protect ordinary freight access and set subsidy limits so support remains affordable."),
             ("An internet connection that works", "Map gaps and set minimum performance standards. Tender support where commercial networks will not deliver and require open wholesale access when public money pays. Farms, clinics, schools and small firms need usable connections, with backup arrangements ready for the storms that interrupt normal service."),
             ("Protect tomorrow's harvest and catch", "Set fishing limits over several years using independent stock assessments, with transparent allocations and fair access for small operators. Improve vessel monitoring, traceability and biosecurity. Allow independently assessed field trials of resilient crops and gene editing, with safety evidence determining which trials can proceed."),
             ("Let regions make practical decisions", "Give regional leaders transport, skills and water budgets covering several years, with clear service outcomes. Local choices must respect national rights, safety and fiscal rules. Report investment, employment and service results by region so communities can see what their agreement has delivered."),
         ], delivery="By 2069: regional growth agreements, rural water priorities and a public map of broadband gaps and repairs."),
    dict(id="fiscal-rules", part=1, title="Rules that protect tomorrow.",
         intro="Debt is down to 69% of GDP. That gives Caprica a stronger starting point. The next task is to keep services dependable, invest carefully and leave room to meet the next emergency.",
         everyday="Careful public finances help keep essential services reliable through difficult years and prevent today's promises from becoming an unexpected bill for tomorrow's households.",
         test="Gross debt target: 65% by 2072",
         entries=[
             ("Keep debt moving down", "Aim to bring gross debt from 69% of GDP in 2068 to 65% by 2072 under normal economic conditions. Retain the separate statutory net debt ceiling below 70%. Report both measures and contingent liabilities clearly, so assets and accounting changes cannot disguise the true position."),
             ("Keep discipline after the milestone", "Passing the old 70% threshold will not end spending discipline. In normal conditions, current spending should grow no faster than CPI plus population. Exceptions for independently assessed aging, health or other service pressures need identified funding and an explicit vote in Parliament."),
             ("Pay for promises that last", "Fund recurring commitments with recurring revenue or verified permanent savings. Asset sales, temporary windfalls and hoped for growth cannot pay for permanent tax cuts. Protect sovereign wealth principal, and report withdrawals, investment income and obligations separately so people can see what the country owns and owes."),
             ("Make every major project prove itself", "Projects above 1 billion aurums must have an options appraisal, reference design, cost and benefit ranges, a responsible authority and funded maintenance. Apply proportionate checks to smaller projects. Independent reviews release money in stages, with overruns and guarantees reported to Parliament."),
             ("Explain and correct a missed target", "Treasury must issue a correction plan within 30 days when a budget departs from the certified debt path, showing effects on growth and different households. Parliament will set the pace. Explain delays and redesigns, while avoiding automatic cuts that would make a downturn worse."),
             ("Leave room to meet an emergency", "A serious recession, disaster or security emergency can justify a lawful, temporary departure, with a stated ceiling and quarterly reporting. Automatic stabilizers stay outside the ordinary spending ceiling. Any exception requires renewal after 12 months and a realistic plan to return to the rules."),
         ], delivery="First budget: the fiscal framework for 2068 to 2072, independent stress tests and the capital investment pipeline."),
    dict(id="funding", part=1, title="Make the funding part of the promise.",
         intro="An affordable promise is one we can keep. These are the funding routes for our program. Each expansion must pass independent costing before money is committed, with difficult choices made in public.",
         everyday="You can judge the cost alongside the benefit, knowing that a new promise must have real funding before government commits money to it.",
         test="Ten years of costs before budget votes",
         entries=[
             ("Protect help people already rely on", "Prioritize statutory indexation, the earnings credit and essential caring support within the current spending limit. Cost new housing savings relief and shared ownership before allocating places. Further tax rate cuts can proceed only when independent assessment confirms an affordable route to the 2072 debt goal."),
             ("Let development pay its share", "Use disclosed development levies, gains in land value around stations and competitive public land tenders to finance added capacity. Borrow only for independently tested capital projects with repayment plans. Show exposure to falling land prices and never allocate the same expected receipt twice."),
             ("Make training money reach learners", "Redirect genuinely unused training levy balances and combine overlapping grants into accredited places and portable accounts. Preserve service access through the change. Verify contract obligations, administration costs and replacement capacity before counting savings, and show where support reaches regions and families."),
             ("Fund care before banking savings", "Move more commissioning toward primary, community and timely elective care within a budget covering several years. Build staff and treatment capacity first. Expected prevention benefits cannot be spent as cash today, and existing provision must remain until replacement services are working."),
             ("Keep energy funding honest", "Return at least half of emissions auction receipts to households. Remaining receipts can support grid resilience and temporary transition investment, with reserves for volatile revenue. Energy contracts must disclose lasting consumer costs. Variable auction income will not finance permanent public sector payroll."),
             ("Count efficiencies when they arrive", "Redirect verified savings from excess military estate, duplicated procurement and administration into sea, air and reserve readiness, after accounting for transition costs. Audit digital savings after delivery. Include defense guarantees and obligations to private partners in the fiscal accounts so liabilities cannot disappear off the books."),
         ], delivery="Before each budget vote: costs over ten years, assumptions, service effects and an independent affordability assessment."),
    dict(id="health", part=1, title="Care you can count on.",
         intro="When someone you love is ill, you need to know what happens next. Universal coverage should mean a reachable appointment, an understandable referral and safe treatment when it is needed.",
         everyday="You know who is handling your care, how long you should wait and where to turn if the service cannot treat you in time.",
         test="Urgent nonemergency referrals under 25: 14 days",
         entries=[
             ("An appointment within reach", "Set access on the same day for urgent primary care and within seven days for routine appointments, phased with verified staffing. Expand teams and safe pharmacist and nurse practitioner roles. District waiting figures must include people unable to book, making the full demand visible."),
             ("A way through the waiting list", "When an accredited public service misses a clinically defined maximum elective wait, its commissioner must arrange suitable alternative care at no extra charge. All providers face the same quality and reporting rules. Confirm capacity and referral agreements before bringing the guarantee into effect."),
             ("Mental healthcare without the maze", "Provide one assessment pathway, community crisis teams and a named navigator. By 2070, urgent nonemergency referrals for people under 25 must receive first clinical contact within 14 days; emergencies need immediate assessment. Report subsequent treatment waits as well, so an initial conversation leads to care."),
             ("Find illness early, follow it through", "Join cancer screening, diagnosis and treatment with clear regional timelines. Invest in proven precision diagnostics, rehabilitation and speech therapy. Transport support, outreach and appropriate remote care will keep treatment accessible beyond major cities, with personal appointments available when the patient's needs require them."),
             ("Let your record travel with you", "Create a health record patients can access and authorized services can share, with permission controls, access logs and correction rights. Audit and justify emergency access. Better continuity should spare people repeated histories and reduce errors while preserving strict limits on who can see private information."),
             ("Hold every provider to the standard", "Use common measures of mortality, infection, safety incidents and patient experience across public and independent services. Give an independent inspector powers for unannounced visits and enforceable improvements. Contracts must reward quality and continuity, with checks against avoiding people whose treatment is complex or costly."),
         ], delivery="2069: funded district access plans. By 2070: the youth contact standard and public treatment waiting times."),
    dict(id="families", part=1, title="Security through every stage of life.",
         intro="Families make commitments that last for years. Caring for a parent, raising a child or living independently with a disability should come with dependable support and a clear understanding of your choices.",
         everyday="Support fits the way you live, helping you care for someone, keep your independence or plan retirement without navigating a different maze each time.",
         test="Funded respite offer in place by 2070",
         entries=[
             ("Help that fits family life", "Keep refundable family and childcare support equal across family structures. Offer monthly payments and care beyond office hours under common accreditation. Track take up and the costs parents actually pay, ensuring support reaches shift workers, single parents and households outside major cities."),
             ("Give unpaid caregivers some breathing room", "Maintain the caregiver credit and protect pension contributions during intensive caring periods. Introduce a funded minimum respite offer, with local flexibility, practical training and a named coordinator. Explain eligibility and appeals clearly, expanding provision as trained staff and suitable providers become available."),
             ("Make independence a practical choice", "Join home adaptations, community transport and health and support assessments into a coherent service. Provide workplace adaptation vouchers and supported employment, tracking results. Disability help must follow assessed need, so trying a course or a job does not abruptly remove essential care."),
             ("Protect the retirement people earned", "Honor accrued pension rights and assess pension sustainability over the long term. Any prospective change needs clear notice, transition protection and independent costing. Prioritize dependable basic support and accessible care, with permanent funding required before promising increases that future workers must finance."),
             ("A choice about where to age", "Help people stay safely at home through falls prevention, primary care and adaptations, alongside inspected residential options. Build accessible smaller homes near shops and family. Keep telephone and personal service routes available, so receiving an entitlement never depends on mastering a new app."),
             ("A safety net you can understand", "Explain entitlements for working adults in one place, with clear earnings disregards and gradual withdrawal. Require human review before adverse fraud or error decisions and consider hardship in repayment terms. Pursue deliberate organized fraud while protecting valid claims and meaningful appeals."),
         ], delivery="First year: publish the care and pension baseline. By 2070: coordinated assessments and the funded respite offer."),
    dict(id="energy", part=1, title="Reliable power. A lasting climate settlement.",
         intro="The lights must stay on and the bill must make sense. Caprica's progress to net zero should mean dependable power at home and an advantage for the industries choosing to invest here.",
         everyday="A clearer bill, dependable supply and a share of carbon auction revenue make the clean economy something households can see working in daily life.",
         test="At least half of auction receipts returned",
         entries=[
             ("Keep the cap, share the proceeds", "Maintain a binding emissions cap and predictable auctions, returning at least half the receipts to households equally and transparently. Report allowance prices, emissions and payments together. The dividend follows actual revenue, with each payment explained rather than a fixed sum promised from a variable source."),
             ("Pay for power we can count on", "Let storage, demand response, geothermal, advanced nuclear and other dependable clean options compete on cost, reliability and verified emissions. Auctions must distinguish electricity from guaranteed capacity. Contracts will show consumer obligations, performance penalties and backup costs, making the price of reliability explicit."),
             ("Connect projects that are ready", "Give ready projects priority over speculative grid reservations, using clear rules and standard offers. Strengthen networks serving new homes, ports and industry. State connection dates and charges, with independent appeals and cost checks to protect ordinary bill payers from poorly justified project expenses."),
             ("Make the nuclear case in full", "Before buying small modular reactors, require independent regulation, site screening and funded plans for waste and decommissioning. Compare alternatives across their full working lives for cost, safety and reliability. Disclose guarantees and cancellation liabilities, keeping every public obligation inside the national fiscal framework."),
             ("Give households useful energy choices", "Offer voluntary tariffs that reflect the time electricity is used, simple comparison tools and targeted efficiency finance supported by verified savings. Protect vulnerable consumers during installation and disputes. Give host communities clear benefits, with national consent rules upholding necessary infrastructure and environmental standards."),
             ("Build industries that can compete", "Award competitive grants with fixed end dates for exportable clean technology, repair and recycling. Track additional investment, verified emissions effects and jobs; end awards that fail agreed tests. Protect forests, waterways and coasts through measurable conservation and adaptation standards as new industries develop."),
         ], delivery="By 2069: transparent auctions and connection dates. Quarterly reporting on bills, reliability, emissions and dividends."),
    dict(id="networks", part=1, title="Make everyday connections dependable.",
         intro="A dependable bus can make a job possible. Clean water and a working connection should be ordinary facts of life. We will give maintenance and reliable service the attention people already give them.",
         everyday="The journey to work is easier to plan, essential services are maintained, and someone is clearly responsible when water, transport or connectivity falls short.",
         test="A weekly cap across participating networks",
         entries=[
             ("One journey, one fare cap", "Create a compatible payment account with an automatic weekly cap giving the best available price across participating rail, bus and ferry networks. Keep cash or assisted options and a clear apprentice fare. Agree revenue sharing first, protecting useful services on routes with fewer passengers."),
             ("Build rail where it earns its place", "Upgrade the southern high speed corridor through Valcartier, Fiévreau and Syon in independently costed stages, subject to funding and passenger demand checks. Connect stations to local buses and feeder rail. Disclose journey time gains, alternatives, operating subsidies and full business cases before each major construction commitment."),
             ("Give maintenance its proper share", "Set a public minimum for maintenance within transport and water capital budgets. Map asset condition, safety risks and the repair backlog. Prioritize bridges, junctions, pipes and drainage by public value, so keeping a useful service running receives sustained funding and visible scrutiny."),
             ("Someone answerable for clean water", "Require utilities to disclose water tests, leakage and repair schedules for each service area. Independent regulation will enforce quality and investment duties across ownership models. Prioritize emergency repairs and disclose financing costs, failure penalties and responsibility for replacing assets in lasting contracts."),
             ("A reliable connection wherever you live", "Tender public support competitively for underserved areas, with open wholesale access. Report actual speed, reliability and restoration results. Critical clinics, schools and services need backup connections; households need easy switching and compensation when a provider repeatedly fails the standards in its contract."),
             ("Show the whole project bill", "Use standard contracts, transparent variation costs and independent dispute resolution. Show construction, operation, maintenance and financing costs together. A major projects unit will track progress, while the sponsoring minister and named authority remain responsible for decisions, delays and overruns throughout the project."),
         ], delivery="By 2070: shared fare agreements and public reports on network condition, with regional rollout milestones."),
    dict(id="justice", part=1, title="Safe streets. Fair and effective justice.",
         intro="You should feel safe walking home and confident that a crime will be taken seriously. Police need time to police, victims need support and courts need the capacity to reach fair decisions.",
         everyday="A visible local police presence, clear case updates and courts that can handle their workload make safety and fair treatment part of everyday freedom.",
         test="Judges authorize intrusive evidence gathering",
         entries=[
             ("Put officers where people need them", "Strengthen neighborhood teams, specialist units against organized crime and modern forensics, building on national policing standards. Cut duplicate administration so trained officers have more time for their work. Report staffing, response times and complaints, backed by consistent training and independent oversight of police conduct."),
             ("Go after the criminal network", "Join investigators and prosecutors to disrupt money laundering, trafficking and gang logistics. Courts may require proof of the lawful origin of assets linked to serious crime, with legal assistance and appeal. Evidence must justify seizure; owning valuable property is no proof of an offense."),
             ("Give courts room to do their job", "Expand court capacity and digital case management, prioritizing repeated violence and vulnerable victims. Explain delays and adjournments publicly. Protect disclosure, legal representation and the presumption of innocence while improving administration, so a faster hearing remains a fair hearing for everyone involved."),
             ("Keep victims informed and protected", "Provide regular case updates, trauma support, a national witness protection service and legal deadlines for compensation decisions. A victims' code will name each agency's duties and the route to complain. Better coordination will spare survivors repeated accounts and help them secure protection."),
             ("Prevent the next offense", "Combine early family support, school attendance work and mentoring with proportionate consequences for serious repeated offending. Disrupt gang leadership and illicit communications in prisons, while expanding education and rehabilitation. Measure success through public safety and reduced reoffending, with ineffective programs changed or ended."),
             ("Keep police powers tied to evidence", "Require specific judicial authority for intrusive evidence gathering and reject a general encryption backdoor. Risk tools may guide resources but cannot establish suspicion, guilt or grounds for detention. Disclose consequential uses and allow challenges, with named human responsibility and independent review."),
         ], delivery="Annual justice plan: staffing, court capacity, victim support and public reporting under independent oversight."),
    dict(id="defense", part=1, title="An island nation, ready to defend itself.",
         intro="Our food, exports and connections to the world cross the sea. Caprica needs forces able to defend those routes and our territory, with trained people, working equipment and a clear mission.",
         everyday="Protecting shipping, airspace and essential links helps keep daily life secure, while clear missions and honest costs respect both service personnel and taxpayers.",
         test="A funded sea and air plan in 2069",
         entries=[
             ("Make the navy the senior service", "Prioritize submarines, escorts, patrol vessels, unmanned systems and coastal missiles within a funded plan. Layer surveillance and defenses around sea lanes and port approaches. Every purchase must include crews, ammunition, maintenance and infrastructure, so new equipment adds forces that can actually deploy."),
             ("Watch and defend our airspace", "Invest in maritime patrol, airborne early warning, fighters, tankers, strategic lift and resilient air defense. Disperse and strengthen bases and secure communications. Compare compatible systems competitively, including spare parts and training in their lifetime cost before deciding which equipment to buy."),
             ("A smaller, more capable army", "Move from mass formations toward mobile brigades, coastal defense, engineering, special operations and Columbian reinforcement. Equip small units with drones and secure communications. Protect training and personnel support through restructuring, with Parliament told the transition costs and any temporary gaps in capability."),
             ("Reserves ready when called", "Expand trained reserves, specialist civilian skills and stocks against independently tested scenarios. Exercise mobilization and reinforcement with partners. Agree access to merchant shipping and critical logistics in advance, including lawful compensation and clear command arrangements, so emergency plans rest on usable capacity."),
             ("Buy forces we can sustain", "Set out a funded capability plan covering ten years and quarterly public readiness summaries, with confidential scrutiny where necessary. Open procurement to competition and strengthen domestic maintenance. Redirect verified estate and overhead savings after they occur, accounting for transition costs before spending them."),
             ("Give every mission clear limits", "Require lawful authority, achievable aims and a credible exit for the use of force. Seek parliamentary approval beyond immediate defense and prompt review of emergency action. Fulfill treaty commitments while refusing wars without a defined end that seek to remake another country's political system."),
         ], delivery="First year: a costed sea and air capability plan. By 2072: independent readiness tests against assigned missions."),
    dict(id="resilience", part=1, title="A country that keeps going.",
         intro="When a storm hits or a cable fails, ordinary life still has to continue. Hospitals need power, taps need water and families need reliable information before a difficult day becomes a national crisis.",
         everyday="A hospital keeps treating patients, a community knows where to find help and essential supplies keep moving when normal systems are interrupted for weeks.",
         test="Essential services prepared for 30 days",
         entries=[
             ("Find the weak link early", "Maintain a national register of critical infrastructure owners, dependencies, minimum services and recovery targets. Release a useful public summary while protecting sensitive operational details. Regulators will test whether a single supplier, cable or power failure could take several essential services down together."),
             ("Prepare for 30 days of disruption", "Require hospitals, water, telecoms, major ports and public data centers to test plans for prolonged interruption of outside supplies. Cover backup power, consumables, staff and alternative routes. Compliance must demonstrate service capacity through exercises, giving an honest account of what the stored supplies can support."),
             ("Build a trained civil reserve", "Create voluntary medical, engineering, communications and logistics units to assist local authorities and Columbian disaster response. Set clear insurance, employment protection and deployment terms. Regular joint exercises will let public services, community organizations and private operators work together before the real emergency arrives."),
             ("Make the warning reach everyone", "Test cell broadcasts, backup radio and accessible alerts in relevant languages twice a year. Explain evacuation, shelter and transport for people needing extra help. Local hubs will provide backup power, trusted information and practical support when ordinary communication networks are unavailable."),
             ("Keep essential supplies within reach", "Map vulnerable supplies of medicines, fuel, food, transformers, semiconductors and defense components. Diversify sources and use rotating reserves and reciprocal agreements where worthwhile. Compare preparation costs with the harm of disruption, avoiding stocks that cannot be maintained, rotated or used when needed."),
             ("Prepare for the risks of each place", "Share the cost of independently assessed regional plans for floods, coasts, heat and earthquakes. Combine planning rules, natural defenses and targeted engineering. Name who maintains each measure and explain the remaining risks, so communities understand both the protection provided and the preparations still needed."),
         ], delivery="By 2070: tested continuity plans for essential services and public results from regional resilience exercises."),
    dict(id="rights", part=2, title="Your rights are part of the foundation.",
         intro="Your freedom should not depend on whether the government likes your views. Equal rights, private lives and independent courts are part of what makes Caprica a country worth building a future in.",
         everyday="You can speak, believe, disagree and live privately, with a practical route to challenge an institution when it oversteps its lawful authority over you.",
         test="Judicial warrants before intrusive surveillance",
         entries=[
             ("Protect expression and conscience", "Strengthen Bill of Rights protection for political, academic, artistic and religious expression, including the freedom not to believe. Apply precise legal tests to direct threats, harassment and incitement. Peaceful disagreement and criticism of government must remain protected, including speech that those in office find uncomfortable."),
             ("Equal citizenship under the law", "Defend equal treatment, existing marriage rights and protection from unlawful discrimination. Public institutions must serve people fairly, without arbitrary group preferences or penalties for lawful identity or belief. Reasonable accommodation must preserve everyone else's equal access to an essential public service."),
             ("Put real limits on data collection", "Require a specific lawful purpose, proportionate collection and clear retention periods for personal information. Give people access, correction and deletion when retention is no longer justified. An independent commissioner will investigate misuse, order remedies and penalize serious breaches by both government and private operators."),
             ("Require a warrant for intrusion", "Require judicial approval for intrusive surveillance and rapid review of genuine emergency use. Preserve the Nuremberg Act framework with necessity, proportionality and an audit trail. Journalism, peaceful association and political belief must never become surveillance targets merely because they inconvenience those in power."),
             ("Make emergency powers expire", "Give exceptional powers automatic expiry dates, prompt parliamentary scrutiny and renewal only on a public case. Release reasons and records when operational sensitivity allows. Keep courts and independent oversight available during a crisis, requiring government to justify every extension of exceptional authority."),
             ("Make a right possible to enforce", "Keep complaints, legal assistance and appeals accessible. Require clear reasons for adverse decisions and deadlines to correct errors. Report resolution times and compliance with remedies. Someone challenging an unlawful decision should have a usable route to redress, without facing years of unaffordable proceedings."),
         ], delivery="First year: a rights and oversight review with public proposals, implementation dates and enforceable remedies."),
    dict(id="digital", part=2, title="Technology should give you more control.",
         intro="Technology should give you time back and more control over your information. When a system makes a consequential mistake, you deserve an explanation and a person with the authority to put it right.",
         everyday="You spend less time repeating information and retain control of your records, with a real person available when an automated decision needs a challenge.",
         test="A human can review the decision",
         entries=[
             ("One account, entirely your choice", "Offer a secure wallet for verified licenses, tax, benefits and business filings, with separate controls for each purpose. Keep personal, telephone and paper routes where needed. Essential services must remain accessible without a smartphone, commercial account or consent to unrelated uses of personal information."),
             ("Tell government once, keep control", "Reuse verified information only for authorized purposes. Let people see who accessed their record and correct errors simply. Staff access must match their duties; disclose sharing agreements and independent audits, with effective penalties for unauthorized browsing or passing information to someone else."),
             ("A person answerable for the algorithm", "Every consequential automated public decision needs a named official, a stated purpose, a testing record and an explanation to the person affected. Guarantee meaningful human review and appeal. Test for unequal error rates and disable systems unable to meet legal and service standards."),
             ("Keep private conversations secure", "Reject general encryption backdoors and deliberate weaknesses in communications systems. Investigators may seek specific evidence through lawful powers supervised by judges. Support security research and responsible disclosure of vulnerabilities, helping protect the networks that households, banks, hospitals and employers use every day."),
             ("Buy systems that work together", "Require open standards, portable data and proportionate disclosure of public source code. Contracts need exit plans, continuity arrangements and clear public ownership of data. Independently test usability and security before major deployments, introduce systems in stages and explain failures openly when they happen."),
             ("Test the defenses every year", "Require critical public suppliers to verify access continuously, test backups and report incidents. Conduct annual testing by simulated attackers and maintain domestic continuity arrangements. Give smaller operators practical guidance to meet the same security objectives without burying them in procedures they cannot reasonably operate."),
         ], delivery="By 2070: a register of automated decisions, meaningful human appeals and accessible alternatives in every agency."),
    dict(id="government", part=2, title="A government that answers to you.",
         intro="You should not need to know someone to get an answer. Government works better when responsibility is clear, spending is visible and the people who exercise power can be held to account.",
         everyday="You know when to expect an answer, who is responsible and how to appeal, while public spending is open to the scrutiny of anyone.",
         test="Public service deadlines in place by 2069",
         entries=[
             ("Give every application a clear clock", "Set service deadlines for permits, benefits and routine applications, naming the responsible authority and the next step if it misses them. Measure the entire process, including assisted applications and error correction. A case moved to another queue must still count as unfinished work."),
             ("Let everyone follow public money", "Put tenders, beneficial owners, selection reasons, contract changes and results in a searchable register. Disclose ministerial meetings, lobbying and gifts promptly. Privacy and security exceptions must be proportionate and audited, preventing the ordinary business of government from disappearing behind a secrecy label."),
             ("Keep corruption investigations independent", "Protect the prosecutor responsible for corruption and independent watchdogs from ministerial direction. Apply the same law to government, state enterprises and the military. Provide safe channels for lawful whistleblowing, fair investigation and due process, with evidence required before an accusation becomes a finding."),
             ("Keep power within constitutional limits", "Require lawful executive authority, effective parliamentary scrutiny and independent courts. Review electoral rules openly for equal participation, fair representation and reliable administration. Changes must follow public consultation and constitutional procedures, preserving rules that serve voters beyond the convenience of any governing party."),
             ("Make local responsibility clear", "Agree regional service plans with budgets covering several years and national minimum standards. State which government is responsible, where the money comes from and how residents can appeal. Local discretion should make decisions more responsive and leave no doubt about who must fix a failure."),
             ("Give tomorrow a voice today", "Assess major bills for lasting effects on debt, housing, emissions and transfers between generations. Strengthen access to information through enforceable deadlines and public interest tests. Answer material consultation findings and citizen petitions, showing how public participation influenced the decision or why a proposal was rejected."),
         ], delivery="By 2069: service clocks and open registers. Quarterly manifesto reporting with independent audit and correction plans."),
    dict(id="foreign", part=2, title="Open to the world. Clear about our interests.",
         intro="A small country can have a large purpose. Through the Bluespan Doctrine, Caprica will combine openness with sound judgment, building partnerships that advance peace, protect trade and give our people more opportunities.",
         everyday="Stable partnerships protect the routes businesses use, the freedoms citizens value and the ability of a small country to make its own choices.",
         test="A Twin Strait crisis hotline",
         entries=[
             ("Put national interests into practice", "Protect citizens, territorial integrity, maritime trade and a stable regional balance. Bring diplomacy, commerce, science and defense together around an agreed development strategy. State objectives and assess results publicly, so overseas activity has a clear connection to security, useful cooperation and opportunity at home."),
             ("Make the Columbian partnership work", "Meet defined treaty obligations and cooperate on maritime surveillance, disaster response, logistics and infrastructure standards. Keep national parliamentary accountability. Review shared functions regularly, concentrating joint action on tasks partners can do better together and retaining national or local responsibility where that works best."),
             ("Make a shared market usable", "Pursue mutual recognition for professional services, digital identity, procurement and products, with enforceable competition safeguards. Coordinate energy links and subsea cable protection. Clear rules, practical guidance and effective dispute settlement will help small firms and mobile workers use the opportunities that agreements create."),
             ("Keep talking, keep our judgment", "Sustain normalization with OURS after the Kaoqing Communique, support Kerevan's restored territorial integrity and deny Oshmit access to weapons supply chains. Establish a Twin Strait crisis hotline and maritime incident procedures. Verification and credible deterrence will support continued dialogue when relations are difficult."),
             ("Set achievable limits on force", "Use diplomacy, targeted sanctions and coordinated pressure before military action where circumstances allow. Any use of force requires lawful authority, achievable aims and an exit strategy. Reject wars without defined limits to impose a political system, and subject emergency decisions to prompt parliamentary review."),
             ("Build partnerships that leave lasting skills", "Focus development partnerships on disaster resilience, health security, trade, education and accountable institutions. Disclose contracts and measurable results. Scientific and student exchanges will build lasting skills and relationships, with proportionate protection for sensitive technology and security as people learn and work together."),
         ], delivery="Annual statement to Parliament: treaty readiness, market access, diplomatic objectives and results against the national strategy."),
    dict(id="trade-migration", part=2, title="An open country with dependable rules.",
         intro="Caprica prospers when it can sell, invest and exchange ideas with the world. Clear rules and services that keep pace with growth give people confidence that an open country works for them.",
         everyday="Businesses reach more customers, communities can plan for growth and everyone who works here is protected by the same clear rules against exploitation.",
         test="Initial asylum decisions within six months",
         entries=[
             ("Give exporters more doors to open", "Pursue strong agreements in services, digital trade, food, clean technology and maritime commerce across Columbia, Albeuman and other partners. Explain likely gains, adjustment costs and actual results after implementation. Diversify critical buyers and suppliers so dependence on one market cannot hold the economy hostage."),
             ("Screen security risks with clear rules", "Use defined reviews with deadlines for foreign control of critical infrastructure and technology with civilian and military uses. Give reasons and appeals where security allows. Coordinate proportionate, lawful responses to economic coercion with Columbian partners, stating the conditions under which each measure will end."),
             ("Plan the capacity to welcome people", "Ask Parliament to set indicative annual ranges for migration routes using housing, service capacity, shortages and humanitarian duties. Explain the evidence and review results. Recruit for genuine skill gaps while investing in domestic training and the infrastructure communities need as their populations grow."),
             ("One fair standard at work", "Base skilled entry on verified qualifications, genuine offers, shortages, language ability and appropriate sector wages. License recruiters in areas vulnerable to abuse, enforce sponsor duties and punish wage theft. Equal legal protection for migrant workers will prevent exploitation and protect fair competition across the workforce."),
             ("Reach fair protection decisions sooner", "Target initial asylum decisions within six months, with legal support, full appeals on the merits and humane reception. Enforce final refusals while honoring the prohibition on return to persecution and other legal duties. Use intelligence and cooperation against smuggling, with understandable lawful family and protection routes."),
             ("Help newcomers take part", "Provide language and civics routes, timely recognition of qualifications and clear citizenship requirements for residence and serious criminal history. Allow reasonable exceptions for age and disability. Shared constitutional duties and equal citizenship will sit alongside respect for lawful cultural and religious life."),
         ], delivery="Each year: a parliamentary migration plan, review of market diversification and processing times for each route."),
]

EVERYDAY = [
    ("Your first independent step", "A first wage that goes further, a credible apprenticeship and more homes near work. You should be able to make a start and see where it could take you."),
    ("Room for family life", "Childcare help when the bill arrives, strong schools and services you can plan around. Raising a family needs time and confidence as well as a household budget."),
    ("The chance to build something", "Clear taxes, incorporation in a day and public invoices paid on time. A good idea deserves a fair chance, whether it starts in a shop, a workshop or a laboratory."),
    ("A new chapter at work", "Training that travels with you, fair contracts and support that tapers as earnings rise. Changing industries or returning from caring should make use of the experience you already have."),
    ("Care without losing yourself", "Respite, accessible treatment and protected pension rights give caring families more breathing room. Personal and telephone services keep support within reach when an app is not the answer."),
    ("A future close to home", "Clean water, reliable broadband and a useful route to market help communities grow. Leaving for opportunity should be a choice, with worthwhile options in the place that raised you."),
]

